package com.sentinel.evaluation;

import java.util.List;

/**
 * The human-readable "why this happened" for an evaluated action: prioritized reason bullets and
 * concrete recommendations. Assembled from structured data — never generated by a language model.
 */
public record Explanation(List<String> reasons, List<String> recommendations) {
    public Explanation {
        reasons = reasons == null ? List.of() : List.copyOf(reasons);
        recommendations = recommendations == null ? List.of() : List.copyOf(recommendations);
    }
}
